def mul_power(n, k):
    factors = {}
    for i in range(2, k + 1):
        while n % i == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
    if n != 1:
        factors[n] = 1
    result = 1
    for prime, exp in factors.items():
        result *= prime ** ((exp + k - 1) // k)
    return result

def largest_divisible_subset(nums):
    if not nums:
        return []
    nums.sort()
    dp = [[num] for num in nums]
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0 and len(dp[i]) < len(dp[j]) + 1:
                dp[i] = dp[j] + [nums[i]]
    return max(dp, key=len)

def increment_numeric_values(s, k):
