def count_distinct_prime_factors_power(n):
    if n <= 1:
        return 0
    factors = set()
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.add(i)
            n //= i
        i += 1
    if n > 1:
        factors.add(n)
    return len(factors)

